import "core-js/modules/es.set.difference.v2.js";
import "core-js/modules/es.set.intersection.v2.js";
import "core-js/modules/es.set.is-disjoint-from.v2.js";
import "core-js/modules/es.set.is-subset-of.v2.js";
import "core-js/modules/es.set.is-superset-of.v2.js";
import "core-js/modules/es.set.symmetric-difference.v2.js";
import "core-js/modules/es.set.union.v2.js";
import { ref, computed, onMounted, watch, nextTick } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useStore } from 'vuex';
import { ElMessage, ElMessageBox } from 'element-plus';
import axios from 'axios';
import { API_CONFIG } from '@/config/config';
import defaultAvatar from '@/assets/default-avatar.png';
import { extractAndNormalizeId } from '@/store/modules/chat';
import _ from 'lodash';
export default {
  name: 'GroupInfo',
  props: {
    visible: {
      type: Boolean,
      default: false
    },
    groupInfo: {
      type: Object,
      default: () => ({})
    }
  },
  emits: ['update:visible', 'group-updated', 'group-exited'],
  setup(props, {
    emit
  }) {
    const store = useStore();
    const currentUserId = computed(() => store.state.user.id);
    const currentUser = computed(() => store.state.user);
    const router = useRouter();
    const route = useRoute();
    const groupMembers = ref([]);
    const isMuted = ref(false);
    const showEditName = ref(false);
    const editGroupName = ref('');
    const showAddMember = ref(false);
    const searchKeyword = ref('');
    const selectedUserIds = ref(new Set());
    const allUsers = ref([]);
    const hoverMemberId = ref(null);
    const userListRef = ref(null);

    // 分页控制
    const pagination = ref({
      page: 1,
      pageSize: 20,
      total: 0,
      loading: false,
      hasMore: true
    });
    const isGroupOwner = computed(() => {
      return props.groupInfo.creator_id === currentUserId.value;
    });

    // 处理头像加载错误
    const handleAvatarError = event => {
      event.target.src = defaultAvatar;
    };
    const getMemberId = member => {
      if (!member) return null;
      return typeof member === 'number' ? member : member.id;
    };
    const validGroupMembers = computed(() => {
      return (groupMembers.value || []).filter(member => member && (typeof member === 'object' || typeof member === 'number') && (member.id !== undefined || typeof member === 'number'));
    });
    const groupAvatarUrls = computed(() => {
      if (!props.groupInfo) return [defaultAvatar];
      const avatarMembers = props.groupInfo.avatar_members || [];
      if (avatarMembers.length > 0) {
        return avatarMembers.slice(0, 9).map(url => getFullUrl(url)).filter(Boolean);
      }
      if (groupMembers.value && groupMembers.value.length > 0) {
        return groupMembers.value.slice(0, 9).map(member => {
          if (typeof member === 'object' && member.photo) {
            return getFullUrl(member.photo);
          }
          return defaultAvatar;
        });
      }
      return [defaultAvatar];
    });

    // 过滤用户列表
    const filteredUsers = computed(() => {
      if (!searchKeyword.value) return allUsers.value;
      const keyword = searchKeyword.value.toLowerCase();
      return allUsers.value.filter(user => user && (user.username && user.username.toLowerCase().includes(keyword) || user.phone && user.phone.includes(keyword) || user.email && user.email.toLowerCase().includes(keyword) || user.id && user.id.toString().includes(keyword)));
    });
    const isUserInGroup = userId => {
      return validGroupMembers.value.some(member => {
        const memberId = typeof member === 'object' ? member.id : member;
        return memberId === userId;
      });
    };

    // 处理用户列表滚动事件
    const handleUserListScroll = () => {
      if (!userListRef.value || pagination.value.loading || !pagination.value.hasMore) {
        return;
      }
      const list = userListRef.value;
      const scrollTop = list.scrollTop;
      const scrollHeight = list.scrollHeight;
      const clientHeight = list.clientHeight;

      // 当滚动到底部时加载更多
      if (scrollTop + clientHeight >= scrollHeight - 50) {
        loadAllUsers();
      }
    };
    const getFullUrl = path => {
      if (!path) return defaultAvatar;
      return path.startsWith('http') ? path : `${API_CONFIG.BASE_URL}${path}`;
    };
    const getAvatarPosition = index => {
      const positions = [{
        top: '0%',
        left: '0%',
        width: '50%',
        height: '50%'
      }, {
        top: '0%',
        left: '50%',
        width: '50%',
        height: '50%'
      }, {
        top: '50%',
        left: '0%',
        width: '50%',
        height: '50%'
      }, {
        top: '50%',
        left: '50%',
        width: '50%',
        height: '50%'
      }, {
        top: '16%',
        left: '16%',
        width: '33%',
        height: '33%'
      }, {
        top: '16%',
        right: '16%',
        width: '33%',
        height: '33%'
      }, {
        bottom: '16%',
        left: '16%',
        width: '33%',
        height: '33%'
      }, {
        bottom: '16%',
        right: '16%',
        width: '33%',
        height: '33%'
      }, {
        top: '33%',
        left: '33%',
        width: '33%',
        height: '33%'
      }];
      return positions[index] || positions[0];
    };
    const getMemberAvatar = member => {
      if (!member) return defaultAvatar;
      if (typeof member === 'number') {
        return defaultAvatar;
      }
      if (!member.photo) {
        return defaultAvatar;
      }
      return getFullUrl(member.photo);
    };
    const getMemberRole = member => {
      if (!member) return '成员';
      const memberId = typeof member === 'number' ? member : member.id;
      if (memberId === props.groupInfo.creator_id) return '群主';
      return '成员';
    };
    const getMemberName = member => {
      if (!member) return '未知用户';
      if (typeof member === 'number') return `用户 ${member}`;
      return member.username || `用户 ${member.id}`;
    };
    const getMemberKey = member => {
      if (typeof member === 'number') return member;
      if (member && member.id) return member.id;
      return Math.random();
    };
    const canRemoveMember = member => {
      if (!member) return false;
      const memberId = typeof member === 'number' ? member : member.id;
      if (!memberId) return false;
      if (memberId === currentUserId.value) return false;
      if (memberId === props.groupInfo.creator_id) return false;
      return true;
    };
    const close = () => {
      emit('update:visible', false);
    };
    const loadGroupMembers = async () => {
      try {
        const response = await axios.get(`${API_CONFIG.BASE_URL}/group/${props.groupInfo.group_id}/members`, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data) {
          const membersData = response.data.group_members || [];
          if (Array.isArray(membersData) && membersData.length > 0) {
            if (typeof membersData[0] === 'number') {
              groupMembers.value = membersData.map(id => ({
                id: id,
                username: `用户 ${id}`,
                photo: null
              }));
            } else {
              groupMembers.value = membersData.filter(member => member && typeof member === 'object' && member.id !== undefined);
            }
          } else {
            groupMembers.value = [];
          }
        }
      } catch (error) {
        console.error('加载群成员失败:', error);
        ElMessage.error('加载群成员失败');
      }
    };

    // 加载所有用户
    const loadAllUsers = async () => {
      try {
        if (!pagination.value.hasMore || pagination.value.loading) {
          return;
        }
        pagination.value.loading = true;
        const response = await axios.get(`${API_CONFIG.BASE_URL}/user/get-users`, {
          params: {
            page: pagination.value.page,
            page_size: pagination.value.pageSize
          },
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        console.log("加载到的所有用户数据:", response.data);
        if (response.data && Array.isArray(response.data.data)) {
          const memberIds = new Set(validGroupMembers.value.map(m => typeof m === 'number' ? m : m.id));
          const newUsers = response.data.data.filter(user => user && user.id && !memberIds.has(user.id));

          // 合并用户列表
          allUsers.value = [...allUsers.value, ...newUsers];

          // 更新分页信息
          pagination.value.total = response.data.total || 0;
          pagination.value.hasMore = allUsers.value.length < pagination.value.total;
          if (pagination.value.hasMore) {
            pagination.value.page += 1;
          }
          console.log("过滤后的可添加用户列表:", allUsers.value);
        }
      } catch (error) {
        console.error('加载用户列表失败:', error);
        ElMessage.error('加载用户列表失败');
      } finally {
        pagination.value.loading = false;
      }
    };
    const handleSearchInput = _.debounce(() => {}, 300);
    const showEditNameDialog = () => {
      editGroupName.value = props.groupInfo.group_name || '';
      showEditName.value = true;
    };
    const cancelEditName = () => {
      showEditName.value = false;
    };
    const confirmEditName = async () => {
      try {
        const response = await axios.post(`${API_CONFIG.BASE_URL}/group/update-name`, {
          group_id: props.groupInfo.group_id,
          name: editGroupName.value
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          ElMessage.success('群名称修改成功');
          showEditName.value = false;
          emit('group-updated');
        } else {
          ElMessage.error(response.data.message || '修改失败');
        }
      } catch (error) {
        console.error('修改群名称失败:', error);
        ElMessage.error('修改群名称失败');
      }
      showEditName.value = false;
    };
    const toggleMute = async () => {
      try {
        const response = await axios.post(`${API_CONFIG.BASE_URL}/group/${props.groupInfo.group_id}/mute?user_id=${currentUserId.value}`, {
          muted: !isMuted.value,
          user_id: currentUserId.value
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          isMuted.value = !isMuted.value;
          ElMessage.success(isMuted.value ? '已开启消息免打扰' : '已关闭消息免打扰');
        }
      } catch (error) {
        console.error('设置消息免打扰失败:', error);
        ElMessage.error('设置失败');
      }
    };

    // 其他方法保持不变（removeMember、dismissGroup、exitGroup等）

    const showAddMemberDialog = async () => {
      // 重置分页和用户列表
      pagination.value = {
        page: 1,
        pageSize: 20,
        total: 0,
        loading: false,
        hasMore: true
      };
      allUsers.value = [];
      selectedUserIds.value.clear();
      searchKeyword.value = '';
      showAddMember.value = true;
      await nextTick();
      await loadAllUsers();
    };
    const closeAddMemberDialog = () => {
      showAddMember.value = false;
    };
    const selectUser = user => {
      if (selectedUserIds.value.has(user.id)) {
        selectedUserIds.value.delete(user.id);
      } else {
        selectedUserIds.value.add(user.id);
      }
    };
    const isUserSelected = userId => {
      return selectedUserIds.value.has(userId);
    };
    const confirmAddMembers = async () => {
      if (selectedUserIds.value.size === 0) {
        ElMessage.warning('请选择要添加的成员');
        return;
      }
      try {
        const response = await axios.post(`${API_CONFIG.BASE_URL}/group/add-members`, {
          group_id: props.groupInfo.group_id,
          user_ids: Array.from(selectedUserIds.value)
        }, {
          headers: {
            Authorization: `Bearer ${store.state.token}`
          }
        });
        if (response.data.success) {
          ElMessage.success('成员添加成功');
          await loadGroupMembers();
          closeAddMemberDialog();
          emit('group-updated');
        }
      } catch (error) {
        console.error('添加成员失败:', error);
        ElMessage.error('添加成员失败');
      }
    };
    watch(() => props.visible, async newVisible => {
      if (newVisible && props.groupInfo.group_id) {
        await loadGroupMembers();
        try {
          const response = await axios.get(`${API_CONFIG.BASE_URL}/group/${props.groupInfo.group_id}/mute-status?user_id=${currentUserId.value}`, {
            headers: {
              Authorization: `Bearer ${store.state.token}`
            }
          });
          if (response.data.success) {
            isMuted.value = response.data.muted;
          }
        } catch (error) {
          console.error('获取免打扰状态失败:', error);
        }
      }
    });
    onMounted(async () => {
      if (props.visible && props.groupInfo.group_id) {
        await loadGroupMembers();
      }
    });
    return {
      currentUserId,
      groupMembers,
      validGroupMembers,
      currentUser,
      isMuted,
      showEditName,
      editGroupName,
      showAddMember,
      searchKeyword,
      selectedUserIds,
      filteredUsers,
      isGroupOwner,
      pagination,
      hoverMemberId,
      userListRef,
      handleAvatarError,
      handleUserListScroll,
      handleSearchInput,
      isUserInGroup,
      getFullUrl,
      getAvatarPosition,
      getMemberAvatar,
      getMemberRole,
      getMemberName,
      getMemberId,
      getMemberKey,
      canRemoveMember,
      close,
      showEditNameDialog,
      cancelEditName,
      confirmEditName,
      toggleMute,
      removeMember,
      dismissGroup,
      exitGroup,
      showAddMemberDialog,
      closeAddMemberDialog,
      selectUser,
      isUserSelected,
      confirmAddMembers
    };
  }
};
